-- IRS exempt-org master file: are the 19 (by EIN) or their named affiliates / look-alikes (by name) or their street addresses registered tax-exempt orgs?
WITH b AS (SELECT EIN, ORG_NAME, IN_CARE_OF, STREET, CITY, STATE, SUBSECTION_CODE, NTEE_CODE, RULING_DATE, REVENUE_AMT, ASSET_AMT, TAX_PERIOD_YYYYMM, FOUNDATION_CODE,
   ' '||REGEXP_REPLACE(UPPER(ORG_NAME),'[^A-Z0-9]+',' ')||' ' nn, UPPER(STREET) st FROM LIBRARY_MARTS.CORPORATE_REGISTRY.CORPORATE_REGISTRY__FED_IRS_EO_BMF),
cores AS (SELECT column1 core FROM VALUES ('AMERICAN POLICE OFFICERS ALLIANCE'),('FIREFIGHTERS AND EMS FUND'),('FIREFIGHTERS SUPPORT FUND'),('NATIONAL POLICE SUPPORT FUND'),('COMMITTEE FOR POLICE OFFICERS DEFENSE'),
  ('AMERICAN VETERANS HONOR FUND'),('AMERICAN BREAST CANCER COALITION'),('NATIONAL COMMITTEE FOR VOLUNTEER FIREFIGHTERS'),('NATIONAL COALITION FOR DISABLED VETERANS'),('VETERANS ACTION NETWORK'),
  ('VETERANS IN DEFENSE OF LIBERTY'),('NATIONAL CANCER ALLIANCE'),('AMERICAN COALITION FOR POLICE'),('UNITED FIREFIGHTERS SUPPORT'),('AMERICAN ALLIANCE FOR MILITARY VETERANS'),
  ('NATIONAL POLICE SHERIFFS COALITION'),('AMERICAN ALLIANCE FOR PUBLIC SAFETY'),('CONSTITUTIONAL POLICING SUPPORT'),('POLICE OFFICERS DEFENSE ALLIANCE'),('POLICE OFFICERS DEFENSE'),('REAL DEMOCRACY FUND'),('CANCER RECOVERY ACTION'),('FIREFIGHTERS SUPPORT ASSOCIATION'),('AMERICAN WOUNDED VETERANS'),('VOLUNTEER FIREFIGHTER PARAMEDIC')),
adr AS (SELECT column1 a FROM VALUES ('2301 SUN VALLEY'),('200 S EXECUTIVE'),('14497 POTOMAC MILLS'),('9480 MAIN ST'),('5801 LEESBURG PIKE'),('110 COLISEUM'),('1 E ERIE'),('1 EAST ERIE'),('2000 COLORADO BLVD'),
  ('1 WASHINGTON MALL'),('900 COMMONWEALTH'),('10521 JUDICIAL'),('4250 FAIRFAX'),('5680 KING CENTRE'),('1101 WILSON'),('1655 FORT MYER'),('2800 EISENHOWER'),('301 S MCDOWELL'),('4301 50TH'),('4210 ELECTRIC'),
  ('7345 W 100TH'),('3804 WILSON'),('7400 BEAUMONT'),('1104 W BROAD'),('1104 WEST BROAD'))
SELECT b.EIN, b.ORG_NAME, b.IN_CARE_OF, b.STREET, b.CITY, b.STATE, b.SUBSECTION_CODE, b.NTEE_CODE, b.RULING_DATE, b.REVENUE_AMT, b.TAX_PERIOD_YYYYMM,
  IFF(b.EIN IN ('821194581','822366231','815214552','843153271','822315009','834686848','843763411','853307234','472041040','273594732','843763242','921706849','922354897','861386683','843763606','922452599','923489519','854325630','923489713'),'EIN','') ein_hit,
  (SELECT LISTAGG(core,'|') FROM cores WHERE b.nn LIKE '% '||core||' %') name_hit,
  (SELECT LISTAGG(a,'|') FROM adr WHERE b.st LIKE a||'%') addr_hit
FROM b
WHERE b.EIN IN ('821194581','822366231','815214552','843153271','822315009','834686848','843763411','853307234','472041040','273594732','843763242','921706849','922354897','861386683','843763606','922452599','923489519','854325630','923489713')
  OR EXISTS (SELECT 1 FROM cores WHERE b.nn LIKE '% '||core||' %')
  OR (EXISTS (SELECT 1 FROM adr WHERE b.st LIKE a||'%') AND REGEXP_LIKE(b.nn,'.*(POLICE|SHERIFF|FIRE|VETERAN|CANCER|MILITARY|TROOPER|LAW ENFORCEMENT|RESPONDER|PUBLIC SAFETY|DISABLED|BREAST).*'))
ORDER BY b.ORG_NAME
